import{_ as t,o,c as a,ag as s}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Database Schema Overview","description":"","frontmatter":{},"headers":[],"relativePath":"reference/schema/index.md","filePath":"reference/schema/index.md"}'),d={name:"reference/schema/index.md"};function n(i,e,r,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="database-schema-overview" tabindex="-1">Database Schema Overview <a class="header-anchor" href="#database-schema-overview" aria-label="Permalink to &quot;Database Schema Overview&quot;">​</a></h1><p><strong>Column-by-column reference: see <a href="./columns.html">columns.md</a>.</strong> This page is the tables-and-relationships overview only.</p><p>VERA&#39;s data lives in <strong>Postgres</strong> (Supabase). Every tenant&#39;s rows are isolated with row-level security keyed off a <code>tenant_id</code> UUID set per request via <code>SET LOCAL app.tenant_id</code>. The bot reads and writes exclusively through the DAL (<code>lib/dal.js</code>) so RLS scoping is uniform across every code path.</p><hr><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th><th>Key operations</th></tr></thead><tbody><tr><td><code>time_entries</code></td><td>Every logged hour</td><td>INSERT, UPDATE, DELETE</td></tr><tr><td><code>projects</code></td><td>Project definitions (parents + period/sprint children)</td><td>INSERT, per-column UPDATE</td></tr><tr><td><code>users</code></td><td>Team members</td><td>INSERT, UPDATE role/status</td></tr><tr><td><code>clients</code></td><td>Client organizations</td><td>INSERT, UPDATE name/status</td></tr><tr><td><code>tasks</code></td><td>Work categories</td><td>INSERT, UPDATE name</td></tr><tr><td><code>project_tasks</code></td><td>Tasks enabled per project</td><td>INSERT (enable), DELETE (disable)</td></tr><tr><td><code>budgets</code></td><td>Per-person hour envelopes</td><td>INSERT, UPDATE hours/status/task/window/shape</td></tr><tr><td><code>disciplines</code></td><td>Functional roles</td><td>INSERT, UPDATE name/status</td></tr><tr><td><code>conversations</code></td><td>24-hour chat history; <code>entities</code> JSONB column holds typed entity references from each turn&#39;s tool calls</td><td>INSERT</td></tr><tr><td><code>pending_pto</code></td><td>Time off requests</td><td>INSERT, UPDATE approval/rejection</td></tr><tr><td><code>unresolved_items</code></td><td>Flagged operational issues</td><td>INSERT, UPDATE status</td></tr><tr><td><code>company_calendar</code></td><td>Holidays and events</td><td>INSERT, DELETE</td></tr><tr><td><code>rate_history</code></td><td>Hourly cost per person (versioned)</td><td>INSERT only</td></tr><tr><td><code>liabilities</code></td><td>Vendor payment commitments</td><td>INSERT, UPDATE status</td></tr><tr><td><code>proposals</code></td><td>Prospective engagements before they become projects (sales-side modelling); console-only, owner/admin</td><td>INSERT, UPDATE, DELETE (draft only)</td></tr><tr><td><code>proposal_roles</code></td><td>Planned staffing lines on a proposal (discipline/person, planned hours, optional T&amp;M rate, optional window/shape)</td><td>INSERT, UPDATE, DELETE</td></tr><tr><td><code>proposal_liabilities</code></td><td>Fixed-fee vendor commitments modelled on a proposal</td><td>INSERT, UPDATE, DELETE</td></tr><tr><td><code>discipline_levels</code></td><td>Per-(discipline, level) salary bands (<code>salary_min</code>/<code>salary_max</code>, levels 1–4) for compensation benchmarking; owner-only, console-only</td><td>INSERT, UPDATE</td></tr><tr><td><code>user_attribute_history</code></td><td>Audit trail for <code>users.level</code> / <code>users.discipline_id</code> changes; owner-only, console-only, audit-silent, forward-only (no backfill)</td><td>INSERT only</td></tr><tr><td><code>message_log</code></td><td>Scheduled-DM delivery log — one row per morning/evening/renewal <code>sendDM</code> attempt, success or failure; owner/admin-only, console-only, pruned to 90 days</td><td>INSERT, DELETE (prune)</td></tr><tr><td><code>time_approvals</code></td><td>T&amp;M-only periodic time approval — one row per <code>(project_id, period)</code> (business rule 28 amendment); owner/admin or PM-of-record, console-only, audit-silent</td><td>INSERT, UPDATE (re-approve, in place)</td></tr><tr><td><code>audit_log</code></td><td>Durable audit trail — one row per audited action (rule 27), recorded whether or not Slack is configured; owner/admin-only, console-only, pruned to 90 days</td><td>INSERT, UPDATE (delivered_to_slack), DELETE (prune)</td></tr></tbody></table><p><code>budgets.start_date</code> / <code>budgets.end_date</code> (migration 0036) are an optional window on an envelope — both nullable, no default. Null (the default, and every envelope before this migration) means today&#39;s behavior: a project-lifetime budget with no sense of timing. A window is a bound, not a schedule, and as of this migration it is storage only — nothing reads it yet.</p><p><code>budgets.week_hours</code> (migration 0037) is an optional shape for an envelope&#39;s hours across the weeks of its window — a JSONB array of <code>{ week, hours }</code>, <code>week</code> always a Monday. Null (the default) means unshaped. A window is a prerequisite: the weeks the shape can describe are exactly the Monday-aligned weeks the window spans. Console-only (owner/manager, never reachable from Slack). <strong>The shape is a forecast the PM owns, never an instruction handed to the person whose hours they are</strong> — no calculation, alert, chip, or signal anywhere may derive from a deviation between the shape and logged time, now or in any future issue. As of this migration it is storage only — nothing consumes it in <code>computeAvailableHours</code>, the capacity heatmap, or the burn-up yet.</p><p><code>proposal_roles.start_date</code> / <code>end_date</code> / <code>week_hours</code> (migration 0038) mirror <code>budgets</code>&#39; window and shape exactly, on a proposal staffing line instead of an allocation envelope — same nullable-by-default columns, same validators (<code>lib/week-shape.js</code>, extracted from <code>envelopes.js</code> so this table doesn&#39;t have to import an operational router), same &quot;a window is a bound, not a schedule&quot; and &quot;the shape is a forecast, never an instruction&quot; rules. Storage + editing only as of this migration — <code>lib/proposal-capacity.js</code> does not read these columns yet; making the capacity simulation overlay proposed demand week-by-week is a deliberate follow-up.</p><p><code>user_attribute_history</code> (migration 0039) records every change to <code>users.level</code> and <code>users.discipline_id</code> — the two compensation-adjacent fields that were previously updated in place with no trace. One row per field changed (<code>field</code> is <code>&#39;level&#39;</code> or <code>&#39;discipline_id&#39;</code>), storing <code>old_value</code>/<code>new_value</code> as text (<code>discipline_id</code> as the id, never the name — names are resolved at render time so a later discipline rename doesn&#39;t rewrite history) so the table can carry other fields later without a migration. <code>user_id</code> is a soft reference, same precedent as <code>discipline_levels.discipline_id</code>. <strong>Forward-only: there is nothing to backfill</strong> — history starts the day this shipped. Written from <code>update_user_role</code> (<code>mcp-server.js</code>) only when the resolved new value differs from the current one — a save that doesn&#39;t actually change level or discipline writes zero rows. The write is best-effort: a history-write failure is logged and swallowed, and never fails the user update it&#39;s attached to (same pattern as <code>checkExceptionQueue</code>&#39;s post-write hook on <code>log_time</code>). Owner-only, console-only (absent from <code>MCP_TOOLS</code>, unreachable from Slack), and <strong>audit-silent</strong> — same reasoning as <code>set_rate</code>&#39;s rule-21 suppression, since level is compensation-adjacent and the audit channel is team-visible. Never read by any operational query in <code>lib/dashboard.js</code>, <code>lib/forecast.js</code>, or <code>lib/availability.js</code>. Displayed as a second &quot;Other changes&quot; section in the rate-history accordion on the console Rates tab (<code>/console/users?tab=rates</code>).</p><p><code>message_log</code> (migration 0043) records every scheduled DM VERA sends — one row per <code>sendDM</code> attempt in <code>reminders.js</code> (morning summary, evening reminder, renewal alert), recorded whether the send succeeded or failed. <code>user_id</code> is a soft reference resolved via a subquery against <code>slack_user_id</code> at write time (null when the Slack ID doesn&#39;t match any current user row); <code>slack_user_id</code>, <code>kind</code>, and <code>body</code> are always recorded, and <code>error</code> carries the Slack error string on a <code>status = &#39;failed&#39;</code> row. The write happens at the single choke point (<code>sendDM</code>), not at its three callers, and is wrapped so a logging failure can never break delivery (same pattern as <code>checkExceptionQueue</code>&#39;s post-write hook on <code>log_time</code>). Pruned to the last 90 days once per morning run, not on every write. Owner/admin-only (<code>isOwnerLevel</code>), console-only (absent from <code>MCP_TOOLS</code>, unreachable from Slack) — these messages carry a person&#39;s own envelope figures and logged hours, so a manager must not see anyone else&#39;s. Never read by any operational query in <code>lib/dashboard.js</code>, <code>lib/forecast.js</code>, or <code>lib/availability.js</code>. Displayed at <code>/console/messages</code>.</p><p><code>time_approvals</code> (migration 0046) and the companion <code>time_entries.billable_hours</code> column implement a scoped amendment to business rule 28 for T&amp;M projects only (issue #2179; see CLAUDE.md for the full amendment). On a T&amp;M project a recorded hour is the invoice line, so the project&#39;s PM (or an owner/admin) gets a periodic, hours-only approval step — <code>time_entries.billable_hours</code> is nullable, no backfill, no CHECK, and null means &quot;bill every recorded hour&quot; (today&#39;s behavior, every pre-existing entry unaffected); <code>0</code> is a distinct, legitimate value (&quot;bill none of this&quot;). <code>time_approvals</code> is one row per <code>(project_id, period)</code>, unique together, written by a look-up-then-update-or-insert upsert so re-approving a period updates the same row rather than creating a second one. <code>time_entries.hours</code> itself is never modified by anything in this arc — recorded time stays immutable. Both are console-only (absent from <code>MCP_TOOLS</code>), audit-silent (rule 27 — an approval is neither a create nor a retroactive change to recorded time), and storage/validation/endpoints only as of this migration — no UI yet, and nothing in <code>lib/dashboard.js</code>, <code>lib/forecast.js</code>, <code>lib/availability.js</code>, or <code>reminders.js</code> reads <code>billable_hours</code> or <code>time_approvals</code>.</p><p><code>audit_log</code> (migration 0048, issue #2225) is the durable replacement for audit reaching Slack through two near-identical functions (<code>postAudit</code> in <code>index.js</code>, <code>postConsoleAudit</code> in <code>lib/console-routes.js</code>) that both returned silently when a tenant had no <code>slack_audit_channel_id</code> configured — meaning a Slack-less tenant (a real configuration since #2217/#2219) had no audit trail at all. Every audited action now writes a row here first (the source of truth), then Slack is attempted as one sink among possibly others. <code>event_type</code> is validated in code against a frozen map in <code>lib/audit-events.js</code> (no CHECK constraint, same precedent as <code>message_log.kind</code>) which is also where the leading emoji on <code>message</code> is derived from — never supplied by the call site, so drift between the two audit surfaces is structurally impossible. <code>actor_user_id</code> is a soft reference (nullable); <code>actor_name</code> is denormalized alongside it so a row stays readable after a rename or deactivation, same reasoning as <code>message_log.slack_user_id</code>. <code>message</code> is the full composed line <strong>including</strong> the emoji, so what was recorded is exactly what was posted. <code>delivered_to_slack</code> starts <code>false</code> and is flipped to <code>true</code> only after a successful Slack post — a <code>false</code> row means Slack never got it (no channel configured, no client registered, or the post itself failed), while the durable row always exists regardless. Both the DB write and the Slack post are best-effort (wrapped, logged, swallowed — same shape as <code>checkExceptionQueue</code>&#39;s post-write hook on <code>log_time</code>); an audit failure must never fail the action that triggered it. Pruned to the last 90 days from the same place <code>message_log</code> is pruned (the start of the morning job), no new scheduler. Owner/admin-only, console-only (absent from <code>MCP_TOOLS</code>, unreachable from Slack — the model must never read the audit ledger). Displayed at <code>/console/audit</code>. <strong>Rule 27&#39;s policy of what is audited and what is not is entirely unchanged by this table</strong> — this changes how an audit event travels, not which events exist.</p><p>The migration files (<code>migrations/*.js</code>) are the schema-of-record. <code>docs/reference/schema/columns.md</code> is the working column reference. The DAL reader functions in <code>lib/dal.postgres.js</code> project each table into the object shape callers consume.</p><hr><h2 id="tenant-isolation" tabindex="-1">Tenant isolation <a class="header-anchor" href="#tenant-isolation" aria-label="Permalink to &quot;Tenant isolation&quot;">​</a></h2><p>Every connection enters a <code>withTenant(callback)</code> block that opens a transaction and runs:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LOCAL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tenant_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;tenant uuid&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The runtime role <code>vera_app</code> is <code>NOBYPASSRLS</code>, so policies on every table filter <code>tenant_id = current_setting(&#39;app.tenant_id&#39;)::uuid</code> automatically. Application code never filters by tenant — RLS does it. A query that &quot;forgets&quot; to scope still returns only the current tenant&#39;s rows.</p><p>The privileged <code>postgres</code> role (set via <code>MIGRATION_DATABASE_URL</code>) bypasses RLS and is used only by migrations.</p><hr><h2 id="id-strategy" tabindex="-1">ID strategy <a class="header-anchor" href="#id-strategy" aria-label="Permalink to &quot;ID strategy&quot;">​</a></h2><p>Per-tenant integer IDs are computed at write time as <code>MAX(existing) + 1</code> within the tenant. IDs are <strong>permanent and sequential within a tenant</strong> — never reused, even when records are deleted. Time entry <code>#42</code> always refers to the same entry, enabling reliable audit trails and edit/delete operations via natural language.</p><hr><h2 id="foreign-keys" tabindex="-1">Foreign keys <a class="header-anchor" href="#foreign-keys" aria-label="Permalink to &quot;Foreign keys&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>users ──┬── user_id          ─→ time_entries, budgets, pending_pto, rate_history</span></span>
<span class="line"><span>        ├── pm_user_id       ─→ projects</span></span>
<span class="line"><span>        ├── discipline_id    ─→ disciplines</span></span>
<span class="line"><span>        ├── created_by       ─→ budgets, liabilities</span></span>
<span class="line"><span>        ├── vendor_user_id   ─→ liabilities</span></span>
<span class="line"><span>        └── affected_user_id ─→ unresolved_items</span></span>
<span class="line"><span></span></span>
<span class="line"><span>projects ──┬── project_id       ─→ time_entries, project_tasks, budgets</span></span>
<span class="line"><span>           ├── client_id        ─→ clients</span></span>
<span class="line"><span>           ├── parent_project_id ─→ projects (self-ref, periods/sprints)</span></span>
<span class="line"><span>           └── affected_project_id ─→ unresolved_items</span></span>
<span class="line"><span></span></span>
<span class="line"><span>clients ──── client_id ─→ projects</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tasks ──┬── task_id ─→ time_entries, project_tasks, budgets</span></span></code></pre></div><hr><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><p>Schema is managed by <code>node-pg-migrate</code> (<code>migrations/</code> directory). To apply pending migrations locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:up</span></span></code></pre></div><p>In production this runs automatically on boot via <code>scripts/start.js</code> when <code>MIGRATION_DATABASE_URL</code> is set. An applied migration is recorded in the <code>pgmigrations</code> bookkeeping table; re-running is idempotent.</p><p>For schema changes:</p><ol><li>Create the migration: <code>npx node-pg-migrate create &lt;descriptive_name&gt;</code></li><li>Implement <code>up</code> and <code>down</code></li><li>Apply locally: <code>npm run migrate:up</code></li><li>Update the relevant reader in <code>lib/dal.postgres.js</code> and the typed updater (if applicable)</li><li>Add or update tests in <code>tests/mcp-routes.test.js</code> and <code>tests/dal-postgres.test.js</code></li><li>Update <code>docs/reference/schema/index.md</code> (if a table is added or removed) and <code>docs/reference/schema/columns.md</code> (every schema change touches columns)</li></ol>`,33)])])}const m=t(d,[["render",n]]);export{u as __pageData,m as default};
